function Rng(seed){this.state=(Number(seed)>>>0)||0x9E3779B9;this.level=0;}Rng.prototype.next=function(){var x=this.state;x^=x<<13;x^=x>>>17;x^=x<<5;this.state=x>>>0;return this.state;};Rng.prototype.int=function(a,b){return a+(this.next()%(b-a+1));};Rng.prototype.pick=function(values){var limit=this.level?Math.min(values.length,Math.max(2,Math.ceil(values.length*this.level/5))):values.length;return values[this.int(0,limit-1)];};Rng.prototype.bool=function(){return Boolean(this.next()&1);};Rng.prototype.shuffle=function(values){var a=values.slice();for(var i=a.length-1;i>0;i-=1){var j=this.int(0,i),v=a[i];a[i]=a[j];a[j]=v;}return a;};
