function sameOrigin(a,b){var x=parseUrl(a),y=parseUrl(b);return x.scheme===y.scheme&&x.host===y.host&&x.effectivePort===y.effectivePort;}var SAFE_FIELDS=["accept","accept-language","content-language"];var SAFE_TYPES=["application/x-www-form-urlencoded","multipart/form-data","text/plain"];function corsClassify(req){if(req.sameOrigin)return{kind:"not needed",reasons:[]};var reasons=[];if(!["GET","HEAD","POST"].includes(req.method))reasons.push("method");Object.keys(req.fields||{}).forEach(function(name){var lower=name.toLowerCase();if(lower==="content-type"){if(!SAFE_TYPES.includes(String(req.fields[name]).split(";")[0].trim().toLowerCase()))reasons.push("content-type");}else if(!SAFE_FIELDS.includes(lower))reasons.push("field "+lower);});return{kind:reasons.length?"preflight required":"direct CORS request",reasons:reasons};}function corsExpose(origin,credentials,acao,acac,same){if(same)return true;if(credentials)return acao===origin&&acac===true;return acao==="*"||acao===origin;}function preflightAllows(req,res){var originOk=req.credentials?res.acao===req.origin&&res.acac===true:(res.acao==="*"||res.acao===req.origin),methodOk=res.methods.map(function(x){return x.toUpperCase();}).includes(req.method.toUpperCase()),allowed=res.headers.map(function(x){return x.toLowerCase();}),missing=req.headers.filter(function(x){return!allowed.includes(x.toLowerCase());});return{originOk:originOk,methodOk:methodOk,missing:missing,allowed:originOk&&methodOk&&!missing.length};}function intermediaryKey(urlValue,vary,fields){var u=parseUrl(urlValue),key=u.origin+u.target;vary.forEach(function(name){var lower=name.toLowerCase(),found=Object.keys(fields).find(function(k){return k.toLowerCase()===lower;});key+="|"+lower+"="+(found?fields[found]:"<missing>");});return key;}
function tableBlock(caption,columns,rows){return{kind:"table",caption:caption,columns:columns,rows:rows};}function codeBlock(text){return{kind:"code",text:text};}function noteBlock(text){return{kind:"note",text:text};}function choice(id,label,answer,options){return{id:id,label:label,kind:"choice",answer:String(answer),options:options.map(function(x){return{value:String(x[0]),label:String(x[1])};})};}function typed(id,label,answer,kind){return{id:id,label:label,kind:kind,answer:String(answer)};}function candidate(answer,values,label){var field=candidateInOrder(answer,values,label);field.shuffle=true;return field;}function shuffleCandidateFields(fields,r){fields.forEach(function(f){if(!f.shuffle||f.kind!=="choice")return;var seenLabels=new Set();f.options=f.options.filter(function(o){if(seenLabels.has(o.label)&&o.value!==f.answer)return false;seenLabels.add(o.label);return true;});var correct=f.options.filter(function(o){return o.value===f.answer;})[0].label,labels=r.shuffle(f.options.map(function(o){return o.label;}));f.options=labels.map(function(label,i){return{value:"v"+i,label:label};});f.answer="v"+labels.indexOf(correct);delete f.shuffle;});}function candidateInOrder(answer,values,label){var unique=[],seen=new Set();[answer].concat(values).forEach(function(x){var k=String(x);if(!seen.has(k)){seen.add(k);unique.push(k);}});return choice("answer",label||t("fieldLabels.answer","Answer"),"v0",unique.map(function(x,i){return["v"+i,x];}));}function yesNo(value){return choice("answer",t("fieldLabels.answer","Answer"),value?"yes":"no",[["yes",t("generated.choices.yes","Yes")],["no",t("generated.choices.no","No")]]);}function ex(prompt,blocks,fields,meta){return{title:t("generated.prompts."+prompt,"Choose the exact answer."),blocks:blocks,note:"",fields:fields,meta:meta||{}};}

